import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int l = sc.nextInt();
        String str = sc.next();
        int fs = count(str, "FS");
        int sf = count(str, "SF");
        if (sf > fs) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    static int count(String s, String sub) {
        int cnt = 0;
        int idx = 0;
        while ((idx = s.indexOf(sub, idx)) != -1) {
            cnt++;
            idx += sub.length();
        }
        return cnt;
    }
}
